import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../../services/auth.service';
import { SoftwarePackageService } from '../../services/software-package.service';
import { SoftwarePackageCardComponent } from '../../components/software-package-card/software-package-card.component';
import { SoftwarePackage } from '../../models/software-package';

@Component({
  selector: 'app-software-packages',
  templateUrl: './software-packages.component.html',
  styleUrls: ['./software-packages.component.css']
})
export class SoftwarePackagesComponent implements OnInit {
  searchQuery = '';
  selectedCategory = 'all';
  sortBy = 'title';
  sortOrder = 'asc';
  private searchTimeout: any;

  constructor(
    public router: Router,
    public softwarePackageService: SoftwarePackageService,
    public auth: AuthService
  ) {}

  ngOnInit(): void {
    this.auth.restoreSession();
    this.softwarePackageService.fetchCategories();
    this.softwarePackageService.fetchPackages();
  }

  get isAdmin(): boolean {
    return this.auth.isAdmin;
  }

  get rangeStart(): number {
    return (this.softwarePackageService.currentPage - 1) * this.softwarePackageService.itemsPerPage + 1;
  }

  get rangeEnd(): number {
    return Math.min(this.softwarePackageService.currentPage * this.softwarePackageService.itemsPerPage, this.softwarePackageService.total);
  }

  get visiblePages(): (number | string)[] {
    const total = this.softwarePackageService.totalPages;
    const current = this.softwarePackageService.currentPage;
    const pages: (number | string)[] = [];

    if (total <= 7) {
      for (let i = 1; i <= total; i++) {
        pages.push(i);
      }
    } else {
      pages.push(1);

      if (current > 3) {
        pages.push('...');
      }

      for (let i = Math.max(2, current - 1); i <= Math.min(total - 1, current + 1); i++) {
        pages.push(i);
      }

      if (current < total - 2) {
        pages.push('...');
      }

      pages.push(total);
    }

    return pages;
  }

  handleSearch(): void {
    clearTimeout(this.searchTimeout);
    this.searchTimeout = setTimeout(() => {
      this.softwarePackageService.setSearchQuery(this.searchQuery);
      this.softwarePackageService.fetchPackages();
    }, 500);
  }

  handleCategoryChange(): void {
    this.softwarePackageService.setCategory(this.selectedCategory);
    this.softwarePackageService.fetchPackages();
  }

  handleSortChange(): void {
    this.softwarePackageService.setSorting(this.sortBy, this.sortOrder);
    this.softwarePackageService.fetchPackages();
  }

  goToPage(page: number | string): void {
    if (page === '...' || typeof page !== 'number' || page < 1 || page > this.softwarePackageService.totalPages) {
      return;
    }
    this.softwarePackageService.setPage(page);
    this.softwarePackageService.fetchPackages();
  }

  viewPackage(pkg: SoftwarePackage): void {
    this.router.navigate(['/packages', pkg.id]);
  }

  goToAddPackage(): void {
    this.router.navigate(['/packages', 'new']);
  }

  formatCategory(category: string): string {
    return category
      .split('-')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ');
  }
}
<div class="min-h-screen bg-gray-50">
  <header class="page-header">
    <div class="header-content">
      <div class="flex items-center gap-2">
        <div class="w-6 h-6 bg-primary rounded flex items-center justify-center">
          <svg class="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
        </div>
        <h1 class="page-title">Otua<span class="text-primary">Digital</span></h1>
      </div>
      <nav class="hidden md:flex items-center gap-6">
        <a routerLink="/packages" routerLinkActive="text-primary" class="text-sm font-medium text-gray-700 hover:text-primary transition-colors px-3 py-2 rounded-md">Packages</a>
        <a routerLink="/my-orders" routerLinkActive="text-primary" class="text-sm font-medium text-gray-700 hover:text-primary transition-colors px-3 py-2 rounded-md">My Orders</a>
        <a routerLink="/packages/new" routerLinkActive="text-primary" class="text-sm font-medium text-gray-700 hover:text-primary transition-colors px-3 py-2 rounded-md" *ngIf="isAdmin">Add Package</a>
        <button (click)="auth.logout()" class="text-sm font-medium text-gray-600 hover:text-red-600 transition-colors px-3 py-2 rounded-md hover:bg-gray-50">Sign out</button>
      </nav>
    </div>
  </header>

  <div class="page-container">
    <div class="flex flex-col lg:flex-row lg:items-start justify-between gap-6 mb-8">
      <div class="flex-1 min-w-0">
        <h2 class="text-2xl font-bold text-gray-900 mb-2">Software Packages</h2>
        <p class="text-gray-600 text-sm">Browse and order software packages</p>
      </div>
    </div>

    <div class="card-base mb-8">
      <div class="card-body">
        <div class="flex flex-col sm:flex-row gap-4 items-start sm:items-center">
          <div class="relative w-full sm:w-80 flex-shrink-0">
            <input [(ngModel)]="searchQuery" (input)="handleSearch()" type="text" placeholder="Search packages..." class="w-full pl-10 pr-4 py-2.5 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all" />
            <svg class="w-4 h-4 text-gray-400 absolute left-3 top-1/2 transform -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>
          <select [(ngModel)]="selectedCategory" (change)="handleCategoryChange()" class="w-full sm:w-48 py-2.5 border border-gray-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all flex-shrink-0">
            <option value="all">All Categories</option>
            <option *ngFor="let category of softwarePackageService.categories" [value]="category">{{ formatCategory(category) }}</option>
          </select>
          <select [(ngModel)]="sortBy" (change)="handleSortChange()" class="w-full sm:w-40 py-2.5 border border-gray-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all flex-shrink-0">
            <option value="title">Sort by Title</option>
            <option value="price">Sort by Price</option>
            <option value="rating">Sort by Rating</option>
          </select>
          <select [(ngModel)]="sortOrder" (change)="handleSortChange()" class="w-full sm:w-32 py-2.5 border border-gray-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-primary focus:border-transparent outline-none transition-all flex-shrink-0">
            <option value="asc">Ascending</option>
            <option value="desc">Descending</option>
          </select>
          <button (click)="goToAddPackage()" *ngIf="isAdmin" class="btn-primary w-full sm:w-auto flex-shrink-0">
            <svg class="w-4 h-4 inline-block mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4" />
            </svg>
            Add Package
          </button>
        </div>
      </div>
    </div>

    <div *ngIf="softwarePackageService.isLoading" class="flex justify-center py-12">
      <div class="inline-block animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
    </div>

    <div *ngIf="!softwarePackageService.isLoading && softwarePackageService.error" class="text-center py-12">
      <div class="text-red-500 mb-2">
        <svg class="w-6 h-6 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      </div>
      <p class="text-sm text-red-600">{{ softwarePackageService.error }}</p>
    </div>

    <div *ngIf="!softwarePackageService.isLoading && !softwarePackageService.error && softwarePackageService.packages.length > 0" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
      <app-software-package-card *ngFor="let pkg of softwarePackageService.packages" [package]="pkg" (click)="viewPackage(pkg)"></app-software-package-card>
    </div>

    <div *ngIf="!softwarePackageService.isLoading && !softwarePackageService.error && softwarePackageService.packages.length === 0" class="text-center py-16">
      <svg class="w-8 h-8 mx-auto text-gray-300 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
      </svg>
      <p class="text-sm text-gray-600">No packages found</p>
      <p class="text-xs text-gray-500 mt-1">Try adjusting your search or filter</p>
    </div>
  </div>
</div>
